func stop_midi(tls *libc.TLS) {
	if !(midi_playing != 0) {
		return
	}
	//	SDL_PauseAudio(1);
	SDL_LockAudio(tls)
	midi_playing = 0
	free_parsed_midi(tls, uintptr(unsafe.Pointer(&parsed_midi)))
	SDL_UnlockAudio(tls)
}

func free_midi_resources(tls *libc.TLS) {
	libc.Xfree(tls, instruments_data)
}

func init_midi(tls *libc.TLS) {
	bp := tls.Alloc(16)
	defer tls.Free(16)
	var dathandle uintptr
	var _ /* size at bp+0 */ int32
	_ = dathandle
	if initialized != 0 {
		return
	}
	initialized = libc.BoolUint8(true1 != 0)
	instruments = uintptr(unsafe.Pointer(&hardcoded_instrument))
	dathandle = open_dat(tls, __ccgo_ts+847, 0)
	instruments_data = load_from_opendats_alloc(tls, int32(1), __ccgo_ts+858, libc.UintptrFromInt32(0), bp)
	if !(instruments_data != 0) {
		libc.Xprintf(tls, __ccgo_ts+862, 0)
	} else {
		num_instruments = libc.Int32FromUint8(**(**byte1)(__ccgo_up(instruments_data)))
		if **(**int32)(__ccgo_up(bp)) == int32(1)+num_instruments*libc.Int32FromInt64(16) {
			instruments = instruments_data + libc.UintptrFromInt32(1)
		} else {
			libc.Xprintf(tls, __ccgo_ts+906, 0)
			num_instruments = int32(1)
		}
	}
	if dathandle != libc.UintptrFromInt32(0) {
		close_dat(tls, dathandle)
	}
}

var initialized uint8

func play_midi_sound(tls *libc.TLS, buffer uintptr) {
	var channel, voice int32
	_, _ = channel, voice
	stop_midi(tls)
	if buffer == libc.UintptrFromInt32(0) {
		return
	}
	init_digi(tls)
	if digi_unavailable != 0 {
		return
	}
	init_midi(tls)
	if !(parse_midi(tls, buffer+8, uintptr(unsafe.Pointer(&parsed_midi))) != 0) {
		libc.Xprintf(tls, __ccgo_ts+967, 0)
		return
	}
	// Initialize the OPL chip.
	opl_reset(tls, (*SDL_AudioSpec)(unsafe.Pointer(digi_audiospec)).Ffreq)
	opl_write_reg(tls, uint16(0x105), uint8(0x01)) // OPL3 enable (note: the PoP1 Adlib sounds don't actually use OPL3 extensions)
	voice = 0
	for {
		if !(voice < int32(NUM_OPL_VOICES)) {
			break
		}
		opl_write_instrument(tls, instruments, libc.Uint8FromInt32(voice))
		voice_instrument[voice] = 0
		voice_note[voice] = uint8(0)
		goto _1
	_1:
		;
		voice = voice + 1
	}
	channel = 0
	for {
		if !(channel < int32(MAX_MIDI_CHANNELS)) {
			break
		}
		channel_instrument[channel] = channel
		goto _2
	_2:
		;
		channel = channel + 1
	}
	midi_current_pos = 0
	midi_current_pos_fract_part = libc.Float32FromInt32(0)
	ticks_to_next_pause = 0
	midi_tracks = parsed_midi.Ftracks
	num_midi_tracks = parsed_midi.Fnum_tracks
	midi_semitones_higher = 0
	us_per_beat = uint32(500000) // default tempo (500000 us/beat == 120 bpm)
	current_midi_tempo_modifier = midi_tempo_modifiers[current_sound]
	ticks_per_beat = parsed_midi.Fticks_per_beat
	mixing_freq = (*SDL_AudioSpec)(unsafe.Pointer(digi_audiospec)).Ffreq
	midi_playing = int16(1)
	SDL_PauseAudio(tls, 0)
}

