//	// seg006:03F0
func get_tile_div_mod(tls *libc.TLS, xpos int32) (r int32) {
	bp := tls.Alloc(32)
	defer tls.Free(32)
	var tblSize, x, xh, xl int32
	_, _, _, _ = tblSize, x, xh, xl
	// Determine tile column (xh) and the position within the tile (xl) from xpos.
	// DOS PoP does this:
	//	obj_xl = tile_mod_tbl[xpos];
	//	return tile_div_tbl[xpos];
	// xpos uses a coordinate system in which the left edge of the screen is 58, and each tile is 14 units wide.
	x = xpos - int32(SCREENSPACE_X)
	xl = x % int32(TILE_SIZEX)
	xh = x / int32(TILE_SIZEX)
	if xl < 0 {
		// Integer division rounds towards zero, but we want to round down.
		xh = xh - 1
		// Modulo returns a negative number if x is negative, but we want 0 <= xl < 14.
		xl = xl + int32(TILE_SIZEX)
	}
	// For compatibility with the DOS version, we allow for overflow access to these tables
	// Considering the case of negative overflow
	if xpos < 0 {
		if libc.Int32FromUint64(libc.Uint64FromInt64(34)/libc.Uint64FromInt64(1))+xpos >= 0 {
			xh = libc.Int32FromUint8(bogus[libc.Int32FromUint64(libc.Uint64FromInt64(34)/libc.Uint64FromInt64(1))+xpos]) // simulating tile_div_tbl[xpos]
			xl = int32(tile_div_tbl[libc.Int32FromUint64(libc.Uint64FromInt64(256)/libc.Uint64FromInt64(1))+xpos])       // simulating tile_mod_tbl[xpos]
		} else {
			libc.Xprintf(tls, __ccgo_ts+7917, libc.VaList(bp+8, xpos, -libc.Int32FromUint64(libc.Uint64FromInt64(34)/libc.Uint64FromInt64(1))))
		}
	}
	// Considering the case of positive overflow
	tblSize = int32(256)
	if xpos >= tblSize {
		if xpos-tblSize < libc.Int32FromUint64(libc.Uint64FromInt64(34)/libc.Uint64FromInt64(1)) {
			xh = libc.Int32FromUint8(tile_mod_tbl[xpos-tblSize]) // simulating tile_div_tbl[xpos]
			xl = libc.Int32FromUint8(bogus1[xpos-tblSize])       // simulating tile_mod_tbl[xpos]
		} else {
			libc.Xprintf(tls, __ccgo_ts+7982, libc.VaList(bp+8, xpos, libc.Int32FromUint64(libc.Uint64FromInt64(34)/libc.Uint64FromInt64(1))+tblSize))
		}
	}
	obj_xl = libc.Uint8FromInt32(xl)
	return xh
}

