func locate_file_(tls *libc.TLS, filename uintptr, path_buffer uintptr, buffer_size int32) (r uintptr) {
	if file_exists(tls, filename) != 0 {
		return filename
	} else {
		// If failed, it may be that SDLPoP is being run from the wrong different working directory.
		// We can try to rescue the situation by loading from the directory of the executable.
		return find_first_file_match(tls, path_buffer, buffer_size, __ccgo_ts+4705, filename)
	}
	return r
}

