func idle(tls *libc.TLS) {
	process_events(tls)
	update_screen(tls)
}

func do_simple_wait(tls *libc.TLS, timer_index int32) {
	update_screen(tls)
	for !(has_timer_stopped(tls, timer_index) != 0) {
		SDL_Delay(tls, uint32(1))
		process_events(tls)
	}
}

func do_wait(tls *libc.TLS, timer_index int32) (r int32) {
	var key int32
	_ = key
	update_screen(tls)
	for !(has_timer_stopped(tls, timer_index) != 0) {
		SDL_Delay(tls, uint32(1))
		process_events(tls)
		key = do_paused(tls)
		if key != 0 && (libc.Int32FromUint16(word_1D63A) != 0 || key == int32(0x1B)) {
			return int32(1)
		}
	}
	return 0
}

