func init_timer(tls *libc.TLS, frequency int32) {
	perf_frequency = SDL_GetPerformanceFrequency(tls)
	fps = frequency
	milliseconds_per_tick = libc.Float32FromFloat32(1000) / float32(fps)
	perf_counters_per_tick = perf_frequency / libc.Uint64FromInt32(fps)
	milliseconds_per_counter = libc.Float32FromFloat32(1000) / float32(perf_frequency)
}

