func has_timer_stopped(tls *libc.TLS, timer_index int32) (r int32) {
	var current_counter Uint64
	var overshoot, ticks_elapsed int32
	_, _, _ = current_counter, overshoot, ticks_elapsed
	//PSP: overshoot always too big, 333mhz mandatory to read input!
	current_counter = SDL_GetPerformanceCounter(tls)
	ticks_elapsed = libc.Int32FromUint64(current_counter/perf_counters_per_tick - timer_last_counter[timer_index]/perf_counters_per_tick)
	overshoot = ticks_elapsed - wait_time[timer_index]
	if overshoot >= 0 {
		//		float milliseconds_elapsed = (current_counter - timer_last_counter[timer_index]) * milliseconds_per_counter;
		//		printf("timer %d:   frametime (ms) = %5.1f    fps = %.1f    timer ticks elapsed = %d\n", timer_index, milliseconds_elapsed, 1000.0f / milliseconds_elapsed, ticks_elapsed);
		if overshoot > 0 && overshoot <= int32(3) {
			current_counter = current_counter - libc.Uint64FromInt32(overshoot)*perf_counters_per_tick
		}
		timer_last_counter[timer_index] = current_counter
		return int32(true1)
	} else {
		return false1
	}
	return r
}

